 void setPage(int p){if(welcome)throw std::runtime_error("로그인 후 이용하세요.");if((p==7||p==8)&&!developer())throw std::runtime_error("일관성과 학습은 개발자 전용입니다.");if(p==11&&!developer())throw std::runtime_error("개발자 권한이 필요합니다.");if(p==page)return;save();page=p;formScroll=0;rebuild(false);}
 void scan(){bool changedContent=false;std::vector<fs::path> fresh;auto folder=fs::path(wide(str(store->settings,"output")));auto query=imageSearch?textOf(imageSearch):L"";std::transform(query.begin(),query.end(),query.begin(),::towlower);std::error_code ec;for(auto& p:fs::directory_iterator(folder,ec)){if(!p.is_regular_file(ec)||!imagePath(p.path()))continue;auto stamp=p.last_write_time(ec);auto checked=imageChecks.find(p.path());if(checked==imageChecks.end()||checked->second.first!=stamp){if(checked!=imageChecks.end())changedContent=true;Com<IWICBitmapDecoder> decoder;bool valid=SUCCEEDED(renderer.wic->CreateDecoderFromFilename(p.path().c_str(),nullptr,GENERIC_READ,WICDecodeMetadataCacheOnDemand,&decoder));imageChecks[p.path()]={stamp,valid};}if(!imageChecks[p.path()].second)continue;if(!hardcore()){auto meta=p.path();meta.replace_extension(L".json");try{if(str(readJson(meta).value("settings",json::object()),"content_mode")=="hardcore")continue;}catch(...){}}auto name=p.path().filename().wstring();std::transform(name.begin(),name.end(),name.begin(),::towlower);if(name.find(query)!=std::wstring::npos)fresh.push_back(p.path());}std::sort(fresh.begin(),fresh.end(),[](auto& a,auto& b){std::error_code e;auto t=fs::last_write_time(a,e);auto u=fs::last_write_time(b,e);return t>u;});if(fresh!=paths||changedContent){paths=std::move(fresh);revision++;thumbs.clear();requested.clear();failedImages.clear();images.reset();scroll=0;previewFailed=false;preview.Reset();if(!selected.empty())images.add(selected,revision,true);InvalidateRect(hwnd,nullptr,FALSE);}}
 void select(const fs::path& p){focusPreview=true;selected=p;previewFailed=false;preview.Reset();imageW=imageH=0;images.add(p,revision,true);InvalidateRect(hwnd,nullptr,FALSE);}
 void step(int delta){if(paths.empty())return;auto it=std::find(paths.begin(),paths.end(),selected);int i=it==paths.end()?0:int(it-paths.begin());i=std::clamp(i+delta,0,int(paths.size())-1);select(paths[i]);GalleryLayout grid(browser.w);float row=(i/grid.columns)*grid.tileHeight;scroll=std::max(0.f,row-browser.h/2);}
 void openSelected(){if(!selected.empty())openPath(selected);}

