 void finishProjectDrag(float x,float y){
  if(projectDragKey.empty())return;if(!projectArea.hit(x,y))return;
  std::string source=projectDragKey,targetFolder,before;bool folder=projectDragFolder;
  for(auto& row:projectRows)if(row.rect.hit(x,y)){
   if(folder){if(row.isFolder){if(y<row.rect.y+row.rect.h/2)before=row.key;else{auto& folders=store->doc["folders"];for(size_t i=0;i<folders.size();i++)if(str(folders[i],"id")==row.key&&i+1<folders.size())before=str(folders[i+1],"id");}}else return;}
   else if(row.isFolder)targetFolder=row.key;
   else{targetFolder=row.folder;bool after=y>=row.rect.y+row.rect.h/2;if(!after)before=row.key;else{for(size_t i=0;i+1<projectRows.size();i++)if(projectRows[i].key==row.key&&!projectRows[i+1].isFolder&&projectRows[i+1].folder==targetFolder)before=projectRows[i+1].key;}}
   break;
  }
  save();if(folder)moveProjectFolder(store->doc,source,before);else{moveProject(store->doc,source,targetFolder,before);for(auto& entry:store->doc["folders"])if(str(entry,"id")==targetFolder)entry["collapsed"]=false;}store->save();
 }
 void newProject(bool duplicate=false){save();auto name=inputBox(hwnd,duplicate?L"프로젝트 복제":L"새 프로젝트",duplicate?wide(str(store->current(),"name"))+L" 복사":L"");if(name.empty())return;store->create(utf8(name),duplicate);page=0;formScroll=0;learnedInfo=json::object();archivedAssets=json::array();captionReference.clear();captionResultFile.clear();learningNote.clear();learningAnalysisId.clear();trainingJob.clear();selected.clear();history=json::object();rebuild(false);scan();}
 void switchProject(const std::string& key){save();learnedInfo=json::object();archivedAssets=json::array();captionReference.clear();captionResultFile.clear();learningNote.clear();learningAnalysisId.clear();trainingJob.clear();store->switchTo(key);page=0;formScroll=0;status.clear();store->state["main_tab"]=0;promptTab=std::clamp(store->state.value("prompt_tab",0),0,5);selected.clear();preview.Reset();history=json::object();rebuild(false);scan();if(store->state["selected"].is_string())select(wide(store->state["selected"].get<std::string>()));}
 void projectMenu(){HMENU menu=CreatePopupMenu();std::vector<std::wstring> labels={L"이름 변경",L"고정 / 해제",L"복제",L"닫기",L"닫힌 프로젝트 열기",L"파일 열기",L"파일로 내보내기",L"삭제",L"새 폴더",L"폴더로 이동"};for(int i=0;i<int(labels.size());i++)AppendMenuW(menu,MF_STRING,1+i,labels[i].c_str());POINT p;GetCursorPos(&p);int command=TrackPopupMenu(menu,TPM_RETURNCMD|TPM_NONOTIFY,p.x,p.y,0,hwnd,nullptr);DestroyMenu(menu);if(!command)return;if(command==9){newFolder();return;}if(command==10){projectMoveMenu();return;}save();if(command==1){auto name=inputBox(hwnd,L"프로젝트 이름",wide(str(store->current(),"name")));if(!name.empty())store->current()["name"]=utf8(name);}if(command==2)store->current()["pinned"]=!flag(store->current(),"pinned");if(command==3){newProject(true);return;}if(command==4||command==8){if(engine->locked(store->active)){MessageBoxW(hwnd,L"생성 또는 예약 중인 프로젝트는 닫거나 삭제할 수 없습니다.",L"프로젝트",MB_OK);return;}if(command==8&&MessageBoxW(hwnd,L"프로젝트를 삭제할까요? 이미지 파일은 보존합니다.",L"프로젝트 삭제",MB_YESNO)!=IDYES)return;std::string old=store->active;if(command==4)store->current()["closed"]=true;else{auto& list=store->doc["channels"];list.erase(std::remove_if(list.begin(),list.end(),[&](auto& c){return str(c,"id")==old;}),list.end());}std::string next;for(auto& c:store->doc["channels"])if(!flag(c,"closed")){next=str(c,"id");break;}if(next.empty()){auto key=id();store->doc["channels"].push_back({{"id",key},{"name","새 프로젝트"},{"pinned",false},{"state",newState(store->settings)}});next=key;}store->active=next;store->state=store->current()["state"];store->restore();selected.clear();rebuild(false);scan();}
 if(command==5){HMENU closed=CreatePopupMenu();std::vector<std::string> keys;for(auto& c:store->doc["channels"])if(flag(c,"closed")){keys.push_back(str(c,"id"));AppendMenuW(closed,MF_STRING,keys.size(),wide(str(c,"name")).c_str());}GetCursorPos(&p);int choice=TrackPopupMenu(closed,TPM_RETURNCMD,p.x,p.y,0,hwnd,nullptr);DestroyMenu(closed);if(choice>0){for(auto& c:store->doc["channels"])if(str(c,"id")==keys[choice-1])c["closed"]=false;switchProject(keys[choice-1]);}}
 if(command==6)importProject();if(command==7){auto path=fileDialog(hwnd,true,L"SNUWCANVAS 프로젝트\0*.json\0\0",L"snuwproject.json");if(!path.empty()){auto exported=store->state;for(auto key:{"api","api_key","caption_api_key","caption_api","output"})exported["settings"].erase(key);atomicWrite(path,json{{"format","snuwproject"},{"version",1},{"name",str(store->current(),"name")},{"state",exported}}.dump(2));}}store->save();InvalidateRect(hwnd,nullptr,FALSE);}
 void importProject(){auto path=fileDialog(hwnd,false,L"프로젝트 JSON\0*.json\0\0");if(path.empty())return;auto j=readJson(path);auto state=j.contains("state")?j["state"]:j;if(!state.contains("project"))state={{"settings",store->settings},{"project",j},{"drafts",j.value("prompt_sections",json::object())},{"negative",j.value("negative","")}};auto key=id();state["settings"]["output"]=utf8((store->root/"generated"/key).wstring());store->snapshot();store->doc["channels"].push_back({{"id",key},{"name",j.value("name",utf8(fs::path(path).stem().wstring()))},{"pinned",false},{"state",state}});store->active=key;store->state=state;store->restore();store->save();selected.clear();rebuild(false);scan();}
 void enqueue(bool editing=false){if(welcome)throw std::runtime_error("로그인 후 이용하세요.");save();auto cfg=store->settings;if(!developer()){cfg["consistency_enabled"]=false;cfg["consistency_profile"]="사용 안 함";cfg["style_profile"]="사용 안 함";}cfg["channel_id"]=store->active;cfg["channel_name"]=str(store->current(),"name");auto state=store->state;validate(cfg);auto api=str(cfg,"api");Url checkUrl(api);if(str(cfg,"api_key").find_first_of("\r\n")!=std::string::npos)throw std::runtime_error("API 키 줄바꿈 오류");if(editing&&(str(cfg,"editing_instruction").empty()||!fs::is_regular_file(wide(str(cfg,"editing_image")))))throw std::runtime_error("입력 이미지와 편집 명령을 지정하세요.");std::string req=editing?str(cfg,"editing_request"):"";if(req.empty())req=id();if(editing){store->settings["editing_request"]=req;store->save();}engine->enqueue({store->active,req,cfg,state,editing});InvalidateRect(hwnd,nullptr,FALSE);}
 void preset(bool write){save();auto folder=store->root/"prompts/presets";fs::create_directories(folder);if(write){auto name=inputBox(hwnd,L"프리셋 이름");if(name.empty())return;if(name.find_first_of(L"\\/:*?\"<>|")!=std::wstring::npos)throw std::runtime_error("프리셋 이름에 경로 문자를 사용할 수 없습니다.");atomicWrite(folder/(name+L".json"),store->state["project"].dump(2));}else{auto p=fileDialog(hwnd,false,L"프리셋 JSON\0*.json\0\0");if(p.empty())return;auto j=readJson(p);if(!j.contains("prompt_sections"))throw std::runtime_error("프리셋 형식 오류");store->state["project"]=j;store->state["drafts"]=j["prompt_sections"];store->state["negative"]=j.value("negative","");rebuild(false);save();}}
 void loadText(bool neg=false){auto p=fileDialog(hwnd,false,L"프롬프트\0*.txt\0모든 파일\0*.*\0\0");if(p.empty())return;auto text=readFile(p);if(text.rfind("\xef\xbb\xbf",0)==0)text.erase(0,3);SetWindowTextW(neg?negative:positive,wide(text).c_str());save();}
 void savePrompts(){save();atomicWrite(store->root/"prompts/prompt.txt",str(store->state["drafts"],"prompt"));atomicWrite(store->root/"prompts/negative.txt",str(store->state,"negative"));atomicWrite(store->root/"config/canvas_project.json",store->state["project"].dump(2));}
 void emotion(){std::vector<std::pair<std::wstring,std::string>> options={{L"슬픔","sad expression, downcast eyes, small closed mouth, head slightly lowered, shoulders drawn inward"},{L"화남","angry expression, narrowed eyes, furrowed brows, closed mouth, shoulders squared"},{L"기쁨","happy expression, bright smile, lively eyes, head slightly tilted, relaxed shoulders"},{L"부끄러움","shy expression, blushing cheeks, averted gaze, small closed-mouth smile, shoulders drawn inward"}};HMENU menu=CreatePopupMenu();for(int i=0;i<4;i++)AppendMenuW(menu,MF_STRING,i+1,options[i].first.c_str());POINT p;GetCursorPos(&p);int choice=TrackPopupMenu(menu,TPM_RETURNCMD,p.x,p.y,0,hwnd,nullptr);DestroyMenu(menu);if(choice>0){auto text=textOf(positive);if(!text.empty())text+=L", ";text+=wide(options[choice-1].second);SetWindowTextW(positive,text.c_str());store->state["emotion"]=utf8(options[choice-1].first);save();}}

