 void capabilitiesRequest(){save();auto cfg=store->settings;auto* e=engine;std::thread([cfg,e]{try{NetworkScope modeScope(nullptr,std::chrono::steady_clock::now()+std::chrono::seconds(240),str(cfg,"content_mode","standard"));e->event({"capabilities","","",request("GET",joinUrl(str(cfg,"api"),"/capabilities"),str(cfg,"api_key")).object()});}catch(const std::exception& x){e->event({"error","",x.what(),{}});}}).detach();}
 void historyRequest(const std::string& action){save();auto cfg=store->settings;auto project=store->active;auto session=str(cfg,"editing_session");if(session.empty())throw std::runtime_error("편집할 이미지를 먼저 업로드하세요.");json data=json::object();if(action=="goto"){auto list=history.value("versions",json::array());if(historyIndex<0||historyIndex>=int(list.size()))throw std::runtime_error("버전을 선택하세요.");data["version"]=list[historyIndex]["version"];}auto* e=engine;std::thread([cfg,project,session,action,data,e]{CoInitializeEx(nullptr,COINIT_MULTITHREADED);try{NetworkScope modeScope(nullptr,std::chrono::steady_clock::now()+std::chrono::seconds(240),str(cfg,"content_mode","standard"));auto base=str(cfg,"api"),key=str(cfg,"api_key"),path="/sessions/"+session+"/"+action;auto result=request(action=="history"?"GET":"POST",joinUrl(base,path),key,action=="history"?"":data.dump()).object();auto h=action=="history"?result:request("GET",joinUrl(base,"/sessions/"+session+"/history"),key).object();e->event({"history_ready",project,session,h});if(action!="history")for(auto& row:h["versions"])if(row["version"]==h["current_version"]){Task t{project,id(),cfg,newState(cfg),true};e->download(t,row,"edit_");break;}}catch(const std::exception& x){e->event({"error",project,x.what(),{}});}CoUninitialize();}).detach();}
 void chooseEdit(bool previewImage){save();auto path=previewImage?selected:fs::path(fileDialog(hwnd,false,L"이미지\0*.png;*.jpg;*.jpeg;*.webp\0\0"));if(path.empty())return;store->settings.update({{"editing_image",utf8(path.wstring())},{"editing_session",""},{"editing_job",""},{"editing_request",""}});rebuild(false);save();}
 void addReference(){save();auto path=fileDialog(hwnd,false,L"이미지\0*.png;*.jpg;*.jpeg;*.webp\0\0");if(path.empty())return;auto& refs=store->state["project"]["references"];if(!refs.is_array())refs=json::array();if(refs.size()>=10)throw std::runtime_error("참조는 최대 10장입니다.");refs.push_back({{"path",utf8(path)},{"role","character"},{"weight",0.6},{"end",0.8}});save();InvalidateRect(hwnd,nullptr,FALSE);}
 void updateReference(){sync();auto& refs=store->state["project"]["references"];if(refIndex<0||refIndex>=int(refs.size()))return;refs[refIndex]["role"]=str(store->settings,"_ref_role","character");refs[refIndex]["weight"]=std::stod(str(store->settings,"_ref_weight","0.6"));refs[refIndex]["end"]=std::stod(str(store->settings,"_ref_end","0.8"));save();InvalidateRect(hwnd,nullptr,FALSE);}
 void downloadUrl(){save();auto input=inputBox(hwnd,L"이미지 URL");if(input.empty())return;Task task{store->active,id(),store->settings,store->state,false};auto* e=engine;std::string url=utf8(input);std::thread([task,e,url]{CoInitializeEx(nullptr,COINIT_MULTITHREADED);try{NetworkScope modeScope(nullptr,std::chrono::steady_clock::now()+std::chrono::seconds(240),str(task.cfg,"content_mode","standard"));auto base=str(task.cfg,"api");auto response=request("GET",url,sameOrigin(base,url)?str(task.cfg,"api_key"):"");auto path=fs::path(wide(str(task.cfg,"output")))/("download_"+timestamp()+".png");saveImage(path,response.data);e->event({"image",task.project,utf8(path.wstring()),{}});}catch(const std::exception& x){e->event({"error",task.project,x.what(),{}});}CoUninitialize();}).detach();}
 void exportImage(){if(selected.empty())return;auto p=fileDialog(hwnd,true,L"이미지 파일\0*.png;*.jpg;*.webp\0\0",selected.extension().wstring().c_str()+1);if(!p.empty())fs::copy_file(selected,p,fs::copy_options::overwrite_existing);}
 void modeChanged(const std::string& key){sync();auto& s=store->settings;if(key=="workflow_profile"){restoreModelPreferences(s,store->root,str(s,"_previous_workflow","기존 SDXL"));rebuild(false);store->save();return;}auto profile=str(s,"workflow_profile");bool flux=profile.find("FLUX")!=std::string::npos,fast=profile.find("빠르게")!=std::string::npos;auto mode=str(s,"render_mode");if(key=="workflow_profile"){if(flux){s["cfg"]="1";s["sampler"]="euler";s["scheduler"]="simple";s["steps"]=fast?"4":"20";s["enhance"]=false;s["quality_tags"]=false;s["use_default_negative"]=false;s["hires_enabled"]="끄기";auto w=std::stoi(str(s,"width")),h=std::stoi(str(s,"height"));s["width"]=std::to_string((w+15)/16*16);s["height"]=std::to_string((h+15)/16*16);}}
 if(key=="genre"&&!flux){auto genre=str(s,"genre");s["quality_tags"]=genre=="애니";s["clip_skip"]=genre=="애니"?"-2":"-1";s["use_default_negative"]=false;}
 if(key=="render_mode"&&mode!="사용자 지정"){s["steps"]=flux?(fast?"4":mode=="빠르게"?"12":mode=="균형"?"20":"28"):(mode=="빠르게"?"20":mode=="균형"?"26":"32");s["hires_enabled"]=mode=="고품질"?"켜기":"끄기";if(mode=="고품질"){s["hires_steps"]=flux?(fast?"4":"8"):"10";s["hires_scale"]="1.5";s["hires_denoise"]=flux?"0.2":"0.3";}}if(key=="workflow_profile")applyModelSettings(s,true);else applyModelSettings(s);rebuild(false);store->save();}
 void tick(){if(GetTickCount64()>=nextUpdateCheck&&!engine->busy){nextUpdateCheck=GetTickCount64()+3600000;if(flag(store->settings,"auto_update",true)&&!str(store->settings,"api").empty()){if(updateThread.joinable())updateThread.join();auto cfg=store->settings;auto* e=engine;updateThread=std::thread([this,cfg,e]{try{NetworkScope scope(&updateCancel,std::chrono::steady_clock::now()+std::chrono::seconds(15));auto envelope=request("GET",joinUrl(str(cfg,"api"),"/api/updates/manifest"),"","","application/json",&updateCancel,65536,15000).object();if(flag(envelope,"enabled")){auto release=verifiedRelease(envelope);if(compareVersion(str(release,"version"),CLIENT_VERSION)>0)e->event({"update_available","",str(release,"version"),release});}}catch(...){} });}}bool dirty=false;for(auto& event:engine->take()){dirty=true;if(event.kind=="update_available"){status=L"새 버전 "+wide(event.text)+L" · 재시작하면 업데이트할 수 있습니다.";}else if(event.kind=="developer_reply"){developerReply(event);}else if(event.kind=="learning_reply"){learningReply(event);}else if(event.kind=="settings")store->patchProject(event.project,event.data);else if(event.kind=="image"){if(event.project==store->active&&event.data.contains("analysis_job")&&event.data["analysis_job"].is_object())learningAnalysisId=str(event.data["analysis_job"],"id");if(!str(event.data,"asset_id").empty())serverAssetIds[fs::path(wide(event.text))]=str(event.data,"asset_id");if(event.project==store->active){scan();if(hardcore()||str(event.data,"content_mode")!="hardcore")select(wide(event.text));}log+=L"이미지 저장 완료\r\n";}else if(event.kind=="transfer"){status=wide(event.text);}else if(event.kind=="progress"){if(event.data.contains("usage"))quotaUsage=event.data["usage"];int done=event.data.value("completed",0),count=event.data.value("count",1);auto live=event.data.value("progress",json::object());auto phase=str(live,"stage");double sample=live.value("percent",0.);progress=count?float(100.*(done+std::clamp(sample,0.,99.)/100)/count):0;
 std::map<std::string,std::wstring> phases={{"model_preparing",L"모델 준비 · 생성 시작 중"},{"enhancing_prompt",L"프롬프트 보강 중"},{"preparing",L"생성 준비 중"},{"checking_prompt",L"프롬프트 검사 중"},{"backend_waiting",L"생성 엔진 대기 중"},{"model_loading",L"모델 불러오는 중"},{"model_switching",L"모델 전환 중"},{"model_downloading",L"모델 다운로드 중"},{"sampling",L"이미지 생성 중"},{"processing",L"이미지 처리 중"},{"decoding",L"이미지 디코딩 중"},{"saving",L"이미지 저장 중"},{"inspecting",L"완성 이미지 검사 중"}};
 status=event.text=="queued"?L"서버 대기 중":phases.count(phase)?phases[phase]:L"이미지 생성 중";if(live.contains("percent"))status+=L" "+std::to_wstring(int(sample))+L"%";status+=L" · "+std::to_wstring(done)+L" / "+std::to_wstring(count)+L"장";}else if(event.kind=="started"){status=L"서버 요청 중";progress=0;}else if(event.kind=="done"){status=L"생성 완료";progress=100;log+=wide(event.text)+L"\r\n";}else if(event.kind=="cancelling"||event.kind=="cancelled"){status=wide(event.text);progress=0;store->settings["editing_job"]="";store->settings["editing_request"]="";}else if(event.kind=="error"){status=wide(event.text);log+=L"오류: "+status+L"\r\n";}else if(event.kind=="capabilities"){capabilities=event.data;if(capabilities.contains("usage"))quotaUsage=capabilities["usage"];status=capabilities.value("moderation_ready",true)?L"서버 연결 완료":L"서버 연결됨 · CONTENT_GUARD_MODEL 설정 필요";rebuild();}else if(event.kind=="history_ready"&&event.project==store->active){history=event.data;historyIndex=std::max(0,int(history.value("versions",json::array()).size())-1);}if(page==3&&positive)SetWindowTextW(positive,log.c_str());}
 for(auto& result:images.take()){if(result.revision!=revision)continue;requested.erase(result.path);if(result.failed){failedImages.insert(result.path);if(result.preview&&result.path==selected)previewFailed=true;dirty=true;continue;}renderer.attach(hwnd);auto bitmap=renderer.pixels(result.width,result.height,result.pixels);if(!bitmap){failedImages.insert(result.path);if(result.preview&&result.path==selected)previewFailed=true;dirty=true;continue;}if(result.preview&&result.path==selected){preview=bitmap;imageW=result.originalW;imageH=result.originalH;}else if(!result.preview){thumbs.insert(result.path,bitmap);}dirty=true;}if(projectDragging){float previous=projectScroll;if(mouseY<projectArea.y+24)projectScroll-=12;else if(mouseY>projectArea.y+projectArea.h-24)projectScroll+=12;projectScroll=std::clamp(projectScroll,0.f,std::max(0.f,projectContent-projectArea.h));dirty|=previous!=projectScroll;}if((dirty||engine->busy)&&hwnd)InvalidateRect(hwnd,nullptr,FALSE);}
 void paint();void click(float x,float y,bool twice=false);LRESULT message(UINT,WPARAM,LPARAM);
